function picture(pic, large=false){
  if(PHOTO[pic]){
    return `<img class="machine-photo${large ? ' large' : ''}" src="${PHOTO[pic]}" alt="Ukázka stroje" loading="lazy">`;
  }
  return SVG[pic] || "";
}

