const store = {
  get(k, d){
    try { return JSON.parse(localStorage.getItem(k)) ?? d; }
    catch(e){ return d; }
  },
  set(k, v){
    localStorage.setItem(k, JSON.stringify(v));
  }
};

let current = null;

function nextWorkout(){
  const h = store.get('workouts', []);
  return h.length && h[0].type === 'A' ? 'B' : 'A';
}

const nextWorkoutEl = document.getElementById('nextWorkout');
const nextText = document.getElementById('nextText');
function renderNext(){
  const n = nextWorkout();
  nextWorkoutEl.textContent = n;
  nextText.textContent = n === 'A'
    ? 'Hrudník • záda • nohy • biceps • břicho'
    : 'Hrudník • záda • hýždě • ramena • triceps • břicho';
}

document.querySelectorAll('.tabs button').forEach(b => {
  b.onclick = () => {
    document.querySelectorAll('.tabs button,.tab').forEach(x => x.classList.remove('active'));
    b.classList.add('active');
    document.getElementById(b.dataset.tab).classList.add('active');
    if (b.dataset.tab === 'progress') renderHistory();
  };
});

const freqHint = document.getElementById('freqHint');
document.querySelectorAll('.freq button').forEach(b => {
  b.onclick = () => {
    document.querySelectorAll('.freq button').forEach(x => x.classList.remove('selected'));
    b.classList.add('selected');
    const f = b.dataset.freq;
    freqHint.textContent = f === '1'
      ? 'Jedna návštěva stačí. Příště pokračuj druhým písmenem.'
      : f === '2'
        ? 'A + B. Ideálně mezi nimi den volna. Když můžeš jen sobota + neděle, použij lehčí druhý den.'
        : 'A + B + A; další týden B + A + B. Mezi silovými dny nech pokud možno volno.';
  };
});

function exCard(e, weekend=false){
  let sets = e.sets;
  if (weekend && /leg press|hip thrust/i.test(e.name)) sets = '2×';
  return `<div class="exercise">
    <div class="exercise-head">
      <div class="machine-pic">${picture(e.pic)}</div>
      <div>
        <div class="ex-title">${e.name}</div>
        <div class="ex-sub">${e.muscle} · ${e.reps}</div><div class="ex-alt">Alternativa: ${e.alt}</div>
      </div>
      <div class="sets">${sets}</div>
    </div>
    <div class="ex-actions">
      <button onclick="detail('${e.id}')">Jak na to</button>
      <button onclick="setWeight('${e.id}')">Váha</button>
      <button onclick="doneEx(this)" class="done">✓ Hotovo</button>
    </div>
  </div>`;
}

function findEx(id){
  for (const k of ['A', 'B']) {
    const e = EX[k].find(x => x.id === id);
    if (e) return e;
  }
}

const backToBack = document.getElementById('backToBack');
const elbowPain = document.getElementById('elbowPain');
const kneePain = document.getElementById('kneePain');
const startBtn = document.getElementById('startBtn');
const todayWorkout = document.getElementById('todayWorkout');

function startWorkout(){
  const t = nextWorkout();
  const weekend = backToBack.checked;
  const ep = +elbowPain.value;
  const kp = +kneePain.value;
  current = {type:t, date:new Date().toISOString(), weekend};
  let warn = '';
  if (ep >= 4 || kp >= 4) {
    warn = '<div class="card warning"><b>Dnes je bolest 4/10 nebo víc.</b> Vynech cviky, které oblast zatěžují.</div>';
  }
  todayWorkout.innerHTML =
    warn +
    `<h2 class="work-title">Trénink ${t}</h2>
     <p class="work-note">${weekend ? 'Druhý den po sobě: u nohou a hýždí jen 2 série a žádné honění vah.' : 'První dvě návštěvy: u všech cviků jen 2 pracovní série.'}</p>` +
    EX[t].map(e => exCard(e, weekend)).join('') +
    '<button class="finish" onclick="finishWorkout()">Dokončit trénink</button>';
  todayWorkout.classList.remove('hidden');
  startBtn.textContent = 'Trénink spuštěn';
}
startBtn.onclick = startWorkout;

function doneEx(btn){
  btn.textContent = btn.textContent.includes('✓') ? '↺ Vrátit' : '✓ Hotovo';
  btn.classList.toggle('done');
}

const exerciseModal = document.getElementById('exerciseModal');
const modalContent = document.getElementById('modalContent');
const closeModal = document.getElementById('closeModal');

function detail(id){
  const e = findEx(id);
  const w = store.get('weights', {})[id] || '';
  modalContent.innerHTML = `
    <h2>${e.name}</h2>
    <div class="modal-illustration">${picture(e.pic, true)}</div>
    <div class="weight-row"><b>Poslední váha:</b> <span>${w || 'nezadaná'}${w ? ' kg' : ''}</span></div>
    <h3>Postup</h3>
    <ol class="steps">${e.steps.map(x => `<li>${x}</li>`).join('')}</ol>
    <div class="alt"><b>Alternativní cvik / náhrada:</b> ${e.alt}</div>
    <div class="pain"><b>Pozor:</b> ${e.pain}</div>`;
  exerciseModal.classList.remove('hidden');
}
closeModal.onclick = () => exerciseModal.classList.add('hidden');
exerciseModal.onclick = e => {
  if (e.target.id === 'exerciseModal') exerciseModal.classList.add('hidden');
};

function setWeight(id){
  const old = store.get('weights', {});
  const v = prompt('Zadej pracovní váhu v kg:', old[id] || '');
  if (v !== null && v !== '' && !isNaN(v)) {
    old[id] = +v;
    store.set('weights', old);
  }
}

function finishWorkout(){
  if (!current) return;
  const h = store.get('workouts', []);
  h.unshift(current);
  store.set('workouts', h.slice(0, 100));
  current = null;
  todayWorkout.classList.add('hidden');
  startBtn.textContent = 'Začít trénink';
  renderNext();
  alert('Trénink uložen. Příště aplikace nabídne druhé písmeno.');
}

function renderPlan(){
  for (const t of ['A','B']) {
    document.getElementById('plan' + t).innerHTML =
      `<h2 class="work-title">Trénink ${t}</h2>` + EX[t].map(e => exCard(e, false)).join('');
  }
}

const historyEl = document.getElementById('history');
function renderHistory(){
  const h = store.get('workouts', []);
  const m = store.get('measures', []);
  let html = '';
  h.slice(0, 20).forEach(x => {
    html += `<div class="history-item"><b>Trénink ${x.type}</b><span>${new Date(x.date).toLocaleDateString('cs-CZ')}${x.weekend ? ' · druhý den po sobě' : ''}</span></div>`;
  });
  m.slice(0, 10).forEach(x => {
    html += `<div class="history-item"><b>Měření</b><span>${new Date(x.date).toLocaleDateString('cs-CZ')} · ${x.weight || '–'} kg · pas ${x.waist || '–'} cm · hrudník ${x.chest || '–'} cm · paže ${x.arm || '–'} cm</span></div>`;
  });
  historyEl.innerHTML = html || '<div class="muted">Zatím bez záznamů.</div>';
}

const bodyWeight = document.getElementById('bodyWeight');
const waist = document.getElementById('waist');
const chest = document.getElementById('chest');
const arm = document.getElementById('arm');
const saveMeasure = document.getElementById('saveMeasure');

saveMeasure.onclick = () => {
  const m = store.get('measures', []);
  m.unshift({
    date: new Date().toISOString(),
    weight: bodyWeight.value,
    waist: waist.value,
    chest: chest.value,
    arm: arm.value
  });
  store.set('measures', m.slice(0,100));
  renderHistory();
  alert('Měření uloženo.');
};

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('sw.js').catch(() => {});
}

renderNext();
renderPlan();
renderHistory();